export default function App() {
  const [dark,       toggleDark]    = useTheme();
  const [view,       setView]       = useState('docs');
  const [activeDocId,setActiveDocId]= useState(null);
  const [doc,        setDoc]        = useState(null);
  const [loading,    setLoading]    = useState(false);

  useEffect(() => {
    const h = (e) => { const a=e.target.closest('a[data-doc]'); if(a){e.preventDefault();loadDoc(a.dataset.doc);} };
    document.addEventListener('click', h);
    return () => document.removeEventListener('click', h);
  }, []);

  const loadDoc = useCallback(async (id) => {
    if (!id) { setDoc(null); setActiveDocId(null); return; }
    setActiveDocId(id); setLoading(true); setDoc(null); window.scrollTo(0,0);
    const result = await fetchDoc(id);
    setDoc(result); setLoading(false);
  }, []);

  return (
    <div style={{display:'flex',flexDirection:'column',minHeight:'100vh',background:'var(--bg)'}}>
      <style>{ART_CSS}</style>
      <AppHeader view={view} setView={setView} dark={dark} toggleDark={toggleDark} onSelectDoc={loadDoc}/>
      <div style={{display:'flex',marginTop:56,minHeight:'calc(100vh - 56px)'}}>
        {view==='docs' && (
          <>
            <DocsSidebar activeDocId={activeDocId} onSelect={loadDoc}/>
            <div style={{marginLeft:268,flex:1,display:'flex'}}>
              {loading ? (
                <div style={{padding:'72px 44px',textAlign:'center',flex:1}}>
                  <div style={{width:34,height:34,border:'3px solid var(--border)',borderTopColor:'var(--accent)',borderRadius:'50%',animation:'spin .8s linear infinite',margin:'0 auto 14px'}}/>
                  <div style={{fontSize:13,color:'var(--text-dim)'}}>Loading from GitHub…</div>
                </div>
              ) : !activeDocId ? <DocsHome onSelect={loadDoc}/> : doc ? <DocArticle doc={doc} onSelect={loadDoc}/> : null}
            </div>
          </>
        )}
        {view==='support' && <SupportPortal onViewDocs={()=>setView('docs')}/>}
      </div>
    </div>
  );
}
